  /// Split the leading radix prefix from the value part of this integer literal.
  ///
  /// ```
  /// 10 -> ("", "10")
  /// 0xFFFF -> ("0x", "FFFF")
  /// 0o77 -> ("0o", "77")
  /// 0b1010101 -> ("0b", "1010101")
